    <th>Matricule</th>
    <th>Nom & Prénom</th>
    <th>Statut salarié</th>
    <th>Code Supérieur</th>
    <th>Matricule Supérieur</th>
    <th>Nom & Prénom Supérieur</th>
    <th>Statut Supérieur</th>
  </tr>
</thead>
<tbody>
`;

anomalies.forEach(a => {
  emailText += `
  <tr>
    <td>${a.code_salarie}</td>
    <td>${a.matricule}</td>
    <td>${a.nom} ${a.prenom}</td>
    <td>${a.etat_salarie}</td>
    <td>${a.code_superieur}</td>
    <td>${a.matricule_superieur}</td>
    <td>${a.nom_superieur} ${a.prenom_superieur}</td>
    <td>${a.etat_superieur}</td>
  </tr>
  `;
});

emailText += `
</tbody>
</table>

<p><b>🛠 Action recommandée</b><br>
Merci de vérifier les fiches concernées et de mettre à jour
les supérieurs hiérarchiques si nécessaire.
</p>

<p>
Rapport généré automatiquement par le workflow de contrôle RH.<br>
<b>Services SI</b>
</p>

</body>
</html>
`;

return [{
